const http = require("http");
const fs = require("fs");
const path = require("path");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = fs.mkdtempSync("/tmp/proj-");
fs.writeFileSync(path.join(dir, "index.js"), "export default { async email() {} };\n");
fs.writeFileSync(path.join(dir, "wrangler.json"), JSON.stringify({
  name: "mail-worker", main: "index.js", compatibility_date: "2025-01-01",
  account_id: "acc1", workers_dev: false, preview_urls: false,
  addresses: ["support@example.com"]
}));
const seen = [];
const server = http.createServer((req, res) => {
  let body = "";
  req.on("data", (c) => (body += c));
  req.on("end", () => {
    const p = req.url.replace(/^\/client\/v4/, "").split("?")[0];
    seen.push({ method: req.method, path: p, body });
    let result = null;
    if (p.endsWith("/subdomain")) result = { enabled: false, previews_enabled: false };
    else if (p === "/accounts/acc1/workers/services/mail-worker") result = { default_environment: { script: { tag: "tag123" } } };
    else if (p === "/accounts/acc1/email/routing/rules/plan") result = { zones: [{ zone_id: "zone1", zone_name: "example.com", changes: [{ type: "added", target: "support@example.com" }] }] };
    else if (p === "/zones/zone1/email/routing/rules") result = { id: "rule1" };
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ success: true, errors: [], messages: [], result }));
  });
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "triggers", "deploy"], {
    cwd: dir,
    env: { ...process.env, CI: "true", CLOUDFLARE_API_TOKEN: "test-token", CLOUDFLARE_ACCOUNT_ID: "acc1",
      CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4", WRANGLER_SEND_METRICS: "false",
      WRANGLER_LOG_PATH: "/tmp/wrangler-logs", NO_UPDATE_NOTIFIER: "1", FORCE_COLOR: "0" }
  });
  let out = "";
  child.stdout.on("data", (d) => (out += d));
  child.stderr.on("data", (d) => (out += d));
  const timer = setTimeout(() => { child.kill("SIGKILL"); broken("wrangler triggers deploy timed out: " + out.slice(-500)); }, 80000);
  child.on("close", (code) => {
    clearTimeout(timer);
    server.close();
    if (code !== 0) broken("wrangler triggers deploy exited " + code + ": " + out.slice(-800));
    if (!seen.some((r) => r.method === "POST" && r.path === "/accounts/acc1/workers/scripts/mail-worker/subdomain")) broken("triggers deploy did not reach the mock API: " + out.slice(-500));
    const plan = seen.find((r) => r.method === "POST" && r.path === "/accounts/acc1/email/routing/rules/plan");
    const rule = seen.find((r) => r.method === "POST" && r.path === "/zones/zone1/email/routing/rules");
    if (!plan && !rule && !seen.some((r) => r.path.includes("/email/routing/"))) symptom("wrangler triggers deploy ignored addresses and created no Email Routing rule");
    if (!plan || !rule) broken("unexpected Email Routing requests: " + JSON.stringify(seen.map((r) => r.method + " " + r.path)));
    let b;
    try { b = JSON.parse(rule.body); } catch { broken("rule body is not JSON: " + rule.body); }
    const m = b.matchers && b.matchers[0];
    const a = b.actions && b.actions[0];
    if (!m || m.value !== "support@example.com" || !a || a.type !== "worker" || !a.value || a.value[0] !== "mail-worker") broken("unexpected rule body: " + rule.body);
    console.log("OK: wrangler triggers deploy created an Email Routing rule for support@example.com -> mail-worker");
    process.exit(0);
  });
});

